.btn-primary {
  background: var(--green);
  color: var(--white);
}
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-secondary {
  background: transparent;
  color: var(--green);
  border: 2px solid var(--green);
}
.btn-secondary:hover { background: var(--green-light); }
.btn-white {
  background: var(--white);
  color: var(--forest);
}
.btn-white:hover { background: var(--cream-light); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-cream {
  background: var(--cream);
  color: var(--forest);
}
.btn-cream:hover { background: var(--cream-dark); transform: translateY(-1px); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }
.btn-lg { padding: 16px 32px; font-size: 1rem; }

/* --- Navigation Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--forest);
  box-shadow: var(--shadow-md);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 24px;
  height: 64px;
  max-width: 1400px;
  margin: 0 auto;
}
.header-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--white);
  font-weight: 800;
  font-size: 1.1rem;
  flex-shrink: 0;
}
.logo-icon {
  width: 38px;
  height: 38px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}
.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.nav-link {
  color: rgba(255,255,255,0.85);
  font-size: 0.9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.nav-link:hover, .nav-link.active {
  color: var(--white);
  background: rgba(255,255,255,0.12);
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.btn-signin {
  color: rgba(255,255,255,0.85);
  font-size: 0.9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.btn-signin:hover { color: var(--white); background: rgba(255,255,255,0.12); }
.btn-joinnow {
  background: var(--green);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 8px 18px;
  border-radius: 50px;
  transition: all var(--transition);
}
.btn-joinnow:hover { background: var(--green-dark); }

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--forest);
  color: var(--white);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 24px;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
  transition: transform 0.35s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-content { flex: 1; }
.cookie-content strong { display: block; font-size: 1rem; margin-bottom: 4px; }
.cookie-content p { font-size: 0.85rem; color: rgba(255,255,255,0.75); }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }
.btn-cookie-settings {
  background: transparent;
  border: 1.5px solid rgba(255,255,255,0.4);
  color: rgba(255,255,255,0.85);
  padding: 10px 18px;
  border-radius: 50px;
  font-size: 0.85rem;
  font-weight: 500;
  transition: all var(--transition);
}
.btn-cookie-settings:hover { border-color: var(--white); color: var(--white); }
.btn-cookie-agree {
  background: var(--green);
  color: var(--white);
  padding: 10px 22px;
  border-radius: 50px;
  font-size: 0.85rem;
  font-weight: 600;
  transition: all var(--transition);
}
.btn-cookie-agree:hover { background: var(--green-dark); }

/* --- Hero --- */
.hero {
  background: linear-gradient(135deg, var(--forest) 0%, #1a3317 50%, #2d4a29 100%);
  color: var(--white);
  padding: 100px 24px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,130,74,0.3) 0%, transparent 70%);
  pointer-events: none;
}
.hero-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  position: relative;
  z-index: 1;
}
.hero-label {
  display: inline-block;
  background: rgba(0,130,74,0.3);
  color: var(--cream);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 50px;
  margin-bottom: 20px;
  border: 1px solid rgba(243,206,161,0.3);
}
.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4rem);
  line-height: 1.1;
  margin-bottom: 24px;
  color: var(--cream-light);
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
.hero-visual {
  display: flex;
  justify-content: center;
}
.hero-image-placeholder {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, rgba(243,206,161,0.15) 0%, rgba(0,130,74,0.2) 100%);
  border: 1px solid rgba(243,206,161,0.2);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: rgba(255,255,255,0.4);
  font-size: 0.85rem;
}
.hero-image-placeholder span { font-size: 3rem; }

/* --- Section Spacing --- */
.section { padding: 80px 0; }
.section-sm { padding: 56px 0; }
.section-alt { background: var(--cream-light); }
.section-dark { background: var(--forest); color: var(--white); }
.section-green { background: var(--green); color: var(--white); }
.section-cream { background: var(--cream); }

.section-label {
  display: inline-block;
  background: var(--green-light);
  color: var(--green);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 50px;
  margin-bottom: 16px;
}
.section-dark .section-label {
  background: rgba(255,255,255,0.12);
  color: var(--cream);
}
.section-title {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  margin-bottom: 16px;
  line-height: 1.15;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 560px;
  line-height: 1.7;
}
.section-dark .section-subtitle { color: rgba(255,255,255,0.7); }

/* --- Promo Cards --- */
.promo-grid {
  display: grid;
  gap: 24px;
}
.promo-grid-2 { grid-template-columns: repeat(2, 1fr); }
.promo-grid-3 { grid-template-columns: repeat(3, 1fr); }

.promo-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: transform var(--transition), box-shadow var(--transition);
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.promo-card-inner {
  padding: 48px 40px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 320px;
  justify-content: flex-end;
}
.promo-card-green { background: linear-gradient(145deg, #00824A 0%, #005c35 100%); color: var(--white); }
.promo-card-cream { background: linear-gradient(145deg, #F3CEA1 0%, #e8b870 100%); color: var(--forest); }
.promo-card-forest { background: linear-gradient(145deg, #32462F 0%, #1e2d1c 100%); color: var(--white); }
.promo-card-light { background: var(--cream-light); color: var(--forest); border: 1px solid var(--border); }
.promo-card-soft { background: linear-gradient(145deg, #f0f7f4 0%, #e6f4ee 100%); color: var(--forest); }

.promo-card h3 {
  font-size: clamp(1.4rem, 2.5vw, 1.9rem);
  line-height: 1.2;
}
.promo-card p {
  font-size: 0.95rem;
  line-height: 1.65;
  opacity: 0.85;
}
.promo-tag {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.7;
  margin-bottom: 4px;
}

/* --- Image Placeholder --- */
.img-placeholder {
  background: linear-gradient(135deg, #e8f5ee 0%, #d0e8d8 50%, #b8d8c4 100%);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--green);
  font-size: 0.8rem;
  font-weight: 500;
}
.img-placeholder .icon { font-size: 2.5rem; opacity: 0.6; }

/* --- Footer --- */
.site-footer {
  background: var(--forest);
  color: rgba(255,255,255,0.75);
  padding: 60px 0 32px;
}
.footer-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}
.footer-col h4 {
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
  margin-bottom: 16px;
  letter-spacing: 0.02em;
}
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--cream); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-bottom-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--white);
  font-weight: 700;
}
.footer-bottom p { font-size: 0.8rem; color: rgba(255,255,255,0.45); }
.footer-social { display: flex; gap: 12px; }
.social-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
  transition: all var(--transition);
}
.social-icon:hover { background: var(--green); color: var(--white); }

/* Footer accordion (mobile) */
.footer-col-toggle { display: none; }
.footer-col-header { display: flex; align-items: center; justify-content: space-between; }
.footer-toggle-btn {
  background: none;
  border: none;
  color: rgba(255,255,255,0.5);
  font-size: 1.2rem;
  line-height: 1;
  padding: 4px;
  cursor: pointer;
  transition: transform var(--transition);
}

/* --- Star display --- */
.star { color: #F59E0B; }
.star-outline { color: var(--border); }

/* --- Tabs --- */
.tabs-container { width: 100%; }
.tabs-nav {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.tabs-nav::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 20px;
  border-radius: 50px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--border-light);
  border: 2px solid transparent;
  transition: all var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}
.tab-btn.active, .tab-btn:hover {
  background: var(--green);
  color: var(--white);
}
.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* --- Carousel --- */
.carousel-wrapper { position: relative; }
.carousel-track-container { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex;
  gap: 16px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
}
.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1.5px solid var(--border);
  color: var(--text);
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  box-shadow: var(--shadow-sm);
}
.carousel-btn:hover { background: var(--green); color: var(--white); border-color: var(--green); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }
.carousel-dots { display: flex; gap: 6px; margin-right: auto; }
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--green); width: 20px; border-radius: 4px; }

/* --- Gift Cards --- */
.gift-card {
  flex-shrink: 0;
  width: 220px;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.gift-card:hover { transform: translateY(-6px) scale(1.02); box-shadow: var(--shadow-lg); }
.gift-card-visual {
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  position: relative;
}
.gift-card-info {
  padding: 12px 14px;
  background: var(--white);
}
.gift-card-info h4 {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text);
}
.gift-card-info p {
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-top: 2px;
}

/* --- Tier Cards --- */
.tier-card {
  border-radius: var(--radius-lg);
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: var(--shadow-md);
  transition: transform var(--transition);
}
.tier-card:hover { transform: translateY(-4px); }
.tier-card-green { background: linear-gradient(145deg, #e6f4ee 0%, #d0ead8 100%); border: 2px solid var(--green-light); }
.tier-card-gold { background: linear-gradient(145deg, #FEF9E7 0%, #FDF3C7 100%); border: 2px solid #F59E0B; }
.tier-card-reserve { background: linear-gradient(145deg, #1a1a1a 0%, #2d2d2d 100%); color: var(--white); border: 2px solid #4B5563; }
.tier-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 0.9rem;
}
.tier-badge-green { background: var(--green); color: var(--white); }
.tier-badge-gold { background: #F59E0B; color: var(--white); }
.tier-badge-reserve { background: linear-gradient(90deg, #9F7AEA, #6B46C1); color: var(--white); }
.tier-threshold { font-size: 0.85rem; color: var(--text-muted); }
.tier-card-reserve .tier-threshold { color: rgba(255,255,255,0.6); }
.tier-benefits { display: flex; flex-direction: column; gap: 8px; }
.tier-benefit {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.9rem;
}
.tier-benefit::before {
  content: '✓';
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}
.tier-card-reserve .tier-benefit::before { color: #A78BFA; }

/* --- Step Cards (How it Works) --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.step-card {
  text-align: center;
  padding: 40px 28px;
  border-radius: var(--radius-lg);
  background: var(--white);
  box-shadow: var(--shadow-md);
}
.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-size: 1.3rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}
.step-card h3 { font-size: 1.2rem; margin-bottom: 12px; color: var(--forest); }
.step-card p { font-size: 0.9rem; color: var(--text-muted); line-height: 1.7; }

/* --- Redemption Card --- */
.redemption-display {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 48px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border);
  margin-top: 32px;
}
.redemption-stars {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--green);
  margin-bottom: 8px;
}
.redemption-value {
  display: inline-block;
  background: var(--cream);
  color: var(--brown);
  font-weight: 700;
  font-size: 0.9rem;
  padding: 4px 14px;
  border-radius: 50px;
  margin-bottom: 20px;
}
.redemption-description {
  font-size: 1.2rem;
  color: var(--text);
  margin-bottom: 8px;
  font-weight: 500;
}

/* --- Map / Store Locator --- */
.locator-layout {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 0;
  height: calc(100vh - 64px);
}
.locator-sidebar {
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.locator-controls {
  padding: 20px;
  border-bottom: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.order-toggle {
  display: flex;
  background: var(--border-light);
  border-radius: 50px;
  padding: 4px;
  gap: 4px;
}
.order-toggle-btn {
  flex: 1;
  padding: 8px;
  border-radius: 50px;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-muted);
  text-align: center;
  cursor: pointer;
  transition: all var(--transition);
}
.order-toggle-btn.active {
  background: var(--white);
  color: var(--green);
  box-shadow: var(--shadow-sm);
}
.search-row {
  display: flex;
  gap: 8px;
}
.search-input-wrap {
  flex: 1;
  position: relative;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  font-size: 1rem;
}
.locator-search-input {
  width: 100%;
  padding: 11px 12px 11px 38px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  outline: none;
  transition: border-color var(--transition);
}
.locator-search-input:focus { border-color: var(--green); }
.filter-btn {
  padding: 11px 16px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text);
  background: var(--white);
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all var(--transition);
}
.filter-btn:hover, .filter-btn.active { border-color: var(--green); color: var(--green); background: var(--green-light); }

.search-suggestions {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-md);
  z-index: 50;
  display: none;
}
.search-suggestions.visible { display: block; }
.suggestion-item {
  padding: 10px 14px;
  font-size: 0.88rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  transition: background var(--transition);
}
.suggestion-item:hover { background: var(--green-light); }

.filter-panel {
  padding: 16px 20px;
  background: var(--cream-light);
  border-bottom: 1px solid var(--border);
  display: none;
}
.filter-panel.visible { display: block; }
.filter-panel h4 { font-size: 0.88rem; font-weight: 700; margin-bottom: 12px; color: var(--forest); }
.filter-options { display: flex; flex-direction: column; gap: 8px; }
.filter-option {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.88rem;
  cursor: pointer;
}
.filter-option input[type="checkbox"] { accent-color: var(--green); width: 16px; height: 16px; }

.store-results {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.store-card {
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
  cursor: pointer;
  transition: all var(--transition);
}
.store-card:hover, .store-card.active { border-color: var(--green); background: var(--green-light); }
.store-name { font-size: 0.95rem; font-weight: 700; color: var(--forest); margin-bottom: 4px; }
.store-address { font-size: 0.82rem; color: var(--text-muted); margin-bottom: 8px; }
.store-meta { display: flex; flex-wrap: wrap; gap: 8px; }
.store-tag {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 50px;
  background: var(--cream-light);
  color: var(--forest);
}
.store-tag-open { background: #DCFCE7; color: #166534; }
.store-hours { font-size: 0.8rem; color: var(--text-muted); }

.map-container { position: relative; overflow: hidden; }
.map-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #e8f5ee 0%, #d5ead9 30%, #c5dcc9 60%, #d0e5d4 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.map-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(0,130,74,0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,130,74,0.08) 1px, transparent 1px);
  background-size: 48px 48px;
}
.map-pin {
  position: absolute;
  width: 36px;
  height: 36px;
  background: var(--green);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  box-shadow: var(--shadow-md);
  cursor: pointer;
  transition: transform var(--transition);
}
.map-pin:hover { transform: rotate(-45deg) scale(1.15); }
.map-pin::after {
  content: '☕';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transform: rotate(45deg);
  font-size: 0.9rem;
}
.map-label {
  position: absolute;
  bottom: 20px;
  right: 20px;
  background: var(--white);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  color: var(--text-muted);
  box-shadow: var(--shadow-md);
}

/* --- Menu Sidebar --- */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 0;
  max-width: 1400px;
  margin: 0 auto;
  min-height: calc(100vh - 64px);
}
.menu-sidebar {
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  border-right: 1px solid var(--border);
  padding: 24px 0;
  background: var(--cream-light);
  scrollbar-width: thin;
}
.menu-sidebar::-webkit-scrollbar { width: 4px; }
.menu-sidebar::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
.sidebar-group { margin-bottom: 8px; }
.sidebar-group-label {
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding: 8px 20px 4px;
}
.sidebar-link {
  display: block;
  padding: 9px 20px;
  font-size: 0.9rem;
  color: var(--text);
  transition: all var(--transition);
  border-left: 3px solid transparent;
}
.sidebar-link:hover, .sidebar-link.active {
  color: var(--green);
  background: var(--white);
  border-left-color: var(--green);
}

.menu-content { padding: 32px 40px; }
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 32px;
}
.breadcrumb a { color: var(--green); }
.breadcrumb span { color: var(--text-light); }

.menu-section { margin-bottom: 56px; }
.menu-section-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--forest);
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--border-light);
}
.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 20px;
}
.menu-item {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  transition: all var(--transition);
  cursor: pointer;
}
.menu-item:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); border-color: var(--green-light); }
.menu-item-img {
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.2rem;
}
.menu-item-info { padding: 14px; }
.menu-item-name { font-size: 0.9rem; font-weight: 600; color: var(--forest); margin-bottom: 4px; }
.menu-item-price { font-size: 0.82rem; color: var(--text-muted); }
.menu-item-new {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: var(--green);
  color: var(--white);
  padding: 2px 8px;
  border-radius: 3px;
  margin-bottom: 4px;
}

/* --- Partnership Cards --- */
.partnership-card {
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  align-items: center;
  gap: 24px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.partnership-card:hover { border-color: var(--green); box-shadow: var(--shadow-md); }
.partner-logo {
  width: 72px;
  height: 72px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  flex-shrink: 0;
}
.partnership-card h3 { font-size: 1.05rem; margin-bottom: 6px; color: var(--forest); }
.partnership-card p { font-size: 0.88rem; color: var(--text-muted); }

/* --- App Download --- */
.app-section {
  background: linear-gradient(135deg, var(--forest) 0%, #1e3019 100%);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 64px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.app-badges { display: flex; gap: 12px; margin-top: 24px; flex-wrap: wrap; }
.app-badge {
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(255,255,255,0.12);
  border: 1.5px solid rgba(255,255,255,0.2);
  color: var(--white);
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-size: 0.88rem;
  font-weight: 600;
  transition: all var(--transition);
}
.app-badge:hover { background: rgba(255,255,255,0.2); }
.app-badge span { font-size: 1.4rem; }
.app-mockup {
  display: flex;
  justify-content: center;
}
.phone-mockup {
  width: 200px;
  height: 380px;
  border-radius: 32px;
  background: rgba(255,255,255,0.1);
  border: 2px solid rgba(255,255,255,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}

/* --- Gift Hero --- */
.gift-hero {
  background: linear-gradient(135deg, #1a3a2a 0%, var(--forest) 100%);
  color: var(--white);
  padding: 64px 24px;
  text-align: center;
}
.gift-hero h1 { font-family: var(--font-display); font-size: clamp(2rem, 4vw, 3rem); margin-bottom: 16px; }
.gift-hero p { font-size: 1.05rem; color: rgba(255,255,255,0.8); max-width: 500px; margin: 0 auto 28px; }

/* --- FAQ --- */
.faq-item {
  border-bottom: 1px solid var(--border);
  padding: 20px 0;
}
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  gap: 16px;
}
.faq-question h4 { font-size: 1rem; color: var(--forest); font-weight: 600; }
.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 1.1rem;
  flex-shrink: 0;
  transition: all var(--transition);
}
.faq-item.open .faq-icon { transform: rotate(45deg); border-color: var(--green); color: var(--green); }
.faq-answer {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
  padding-top: 12px;
  display: none;
}
.faq-item.open .faq-answer { display: block; }

/* --- Rewards Hero --- */
.rewards-hero {
  background: linear-gradient(135deg, var(--forest) 0%, #0f2010 100%);
  color: var(--white);
  padding: 80px 24px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.rewards-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(0,130,74,0.25) 0%, transparent 70%);
}
.rewards-hero h1 {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 16px;
  position: relative;
}
.rewards-hero p { font-size: 1.1rem; color: rgba(255,255,255,0.8); max-width: 520px; margin: 0 auto 32px; position: relative; }
.stars-display { font-size: 2rem; margin-bottom: 24px; position: relative; }

/* --- Utilities --- */
.text-center { text-align: center; }
.text-green { color: var(--green); }
.text-forest { color: var(--forest); }
.text-muted { color: var(--text-muted); }
.font-bold { font-weight: 700; }
.mt-4 { margin-top: 16px; }
.mt-8 { margin-top: 32px; }
.mt-12 { margin-top: 48px; }
.mb-4 { margin-bottom: 16px; }
.mb-8 { margin-bottom: 32px; }
.flex { display: flex; }
.gap-4 { gap: 16px; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.w-full { width: 100%; }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .promo-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .app-section { grid-template-columns: 1fr; text-align: center; }
  .app-badges { justify-content: center; }
  .app-mockup { display: none; }
  .menu-layout { grid-template-columns: 240px 1fr; }
  .menu-content { padding: 24px; }
  .locator-layout { grid-template-columns: 340px 1fr; }
}

@media (max-width: 768px) {
  .hero-inner { grid-template-columns: 1fr; text-align: center; }
  .hero-visual { display: none; }
  .hero-actions { justify-content: center; }
  .promo-grid-2 { grid-template-columns: 1fr; }
  .promo-grid-3 { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }

  /* Footer accordion */
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col-toggle { display: block; }
  .footer-col-content { display: none; }
  .footer-col-content.open { display: block; }
  .footer-col { border-bottom: 1px solid rgba(255,255,255,0.1); padding: 16px 0; }
  .footer-col h4 { margin-bottom: 0; }
  .footer-col ul { padding-top: 12px; }
  .footer-col-header { cursor: pointer; }

  .header-nav { display: none; }
  .header-inner { padding: 0 16px; }

  .tier-card { padding: 24px 20px; }
  .redemption-display { padding: 32px 24px; }
  .app-section { padding: 40px 24px; }
  .locator-layout { grid-template-columns: 1fr; height: auto; flex-direction: column; display: flex; }
  .locator-sidebar { height: auto; position: static; max-height: 60vh; }
  .map-container { height: 300px; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { display: none; }
  .cookie-banner { flex-direction: column; gap: 12px; }
  .cookie-actions { width: 100%; justify-content: flex-end; }
  .partnership-card { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .container, .container-wide { padding: 0 16px; }
  .hero { padding: 64px 16px; }
  .section { padding: 56px 0; }
  .promo-card-inner { padding: 32px 24px; }
  .btn-lg { padding: 14px 24px; }
}
