      distance: "0.7 mi",
      hours: "Open · Closes 8:00 PM",
      phone: "(415) 555-0142",
      features: ["mobile", "open"],
      lat: 55, lng: 48
    },
    {
      name: "Westside GreenBean",
      address: "900 Ocean Avenue",
      city: "San Francisco, CA 94122",
      distance: "1.2 mi",
      hours: "Open · Closes 10:00 PM",
      phone: "(415) 555-0178",
      features: ["drive-thru", "mobile", "delivery", "open"],
      lat: 20, lng: 70
    },
    {
      name: "Eastpark Reserve",
      address: "2200 Park Boulevard",
      city: "Oakland, CA 94601",
      distance: "2.4 mi",
      hours: "Open · Closes 7:00 PM",
      phone: "(510) 555-0221",
      features: ["mobile"],
      lat: 70, lng: 68
    },
    {
      name: "Northgate GreenBean",
      address: "750 Gateway Drive",
      city: "San Francisco, CA 94124",
      distance: "3.1 mi",
      hours: "Closes in 30 min",
      phone: "(415) 555-0298",
      features: ["drive-thru", "mobile", "delivery"],
      lat: 45, lng: 82
    }
  ];

  let activeOrderType = 'pickup';
  let activeFilters = { drivethu: false, mobile: false, delivery: false, open: false };
  let selectedStoreIndex = null;

  function featureTag(key) {
    const map = {
      'drive-thru': '🚗 Drive-thru',
      'mobile': '📱 Mobile Order',
      'delivery': '🛵 Delivery',
      'open': 'Open Now'
    };
    return map[key] || key;
  }

  function renderStores(list) {
    const container = document.getElementById('storeResults');
    const countEl = document.getElementById('storeCount');

    if (list.length === 0) {
      container.innerHTML = `<div class="no-results"><div class="icon">🔍</div><div>No stores found.<br>Try a different search or adjust filters.</div></div>`;
      countEl.innerHTML = 'No locations found';
      return;
    }

    countEl.innerHTML = `Showing <strong>${list.length}</strong> location${list.length > 1 ? 's' : ''} near you`;

    container.innerHTML = list.map((s, i) => `
      <div class="store-card ${selectedStoreIndex === i ? 'active' : ''}" role="listitem" onclick="selectStore(${i})" id="store-card-${i}">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:2px;">
          <div class="store-name">${s.name}</div>
          <div class="store-distance">${s.distance}</div>
        </div>
        <div class="store-address">${s.address}, ${s.city}</div>
        <div class="store-hours">${s.hours}</div>
        <div class="store-meta" style="margin-top:8px;">
          ${s.features.map(f => `<span class="store-tag ${f === 'open' ? 'store-tag-open' : ''}">${featureTag(f)}</span>`).join('')}
        </div>
        <div class="store-actions">
          <button class="store-action-btn store-action-btn-primary" onclick="event.stopPropagation();alert('Starting order at ${s.name}')">Order here</button>
          <button class="store-action-btn store-action-btn-secondary" onclick="event.stopPropagation();alert('Getting directions to ${s.name}')">Directions</button>
        </div>
      </div>
    `).join('');
  }

  function applyFilters() {
    activeFilters.drivethu = document.getElementById('filter-drivethu').checked;
    activeFilters.mobile = document.getElementById('filter-mobile').checked;
    activeFilters.delivery = document.getElementById('filter-delivery').checked;
    activeFilters.open = document.getElementById('filter-open').checked;

    let filtered = stores;
    if (activeFilters.drivethu) filtered = filtered.filter(s => s.features.includes('drive-thru'));
    if (activeFilters.mobile) filtered = filtered.filter(s => s.features.includes('mobile'));
    if (activeFilters.delivery) filtered = filtered.filter(s => s.features.includes('delivery'));
    if (activeFilters.open) filtered = filtered.filter(s => s.features.includes('open'));

    // For delivery mode, only show delivery stores
    if (activeOrderType === 'delivery') {
      filtered = filtered.filter(s => s.features.includes('delivery'));
    }

    renderStores(filtered);
  }

  function setOrderType(type) {
    activeOrderType = type;
    document.getElementById('btn-pickup').classList.toggle('active', type === 'pickup');
    document.getElementById('btn-delivery').classList.toggle('active', type === 'delivery');
    applyFilters();
  }

  function toggleFilter() {
    const panel = document.getElementById('filterPanel');
    const btn = document.getElementById('filterBtn');
    const isVisible = panel.classList.contains('visible');
    panel.classList.toggle('visible', !isVisible);
    panel.setAttribute('aria-hidden', isVisible ? 'true' : 'false');
    btn.classList.toggle('active', !isVisible);
    btn.setAttribute('aria-expanded', isVisible ? 'false' : 'true');
  }

  function selectStore(index) {
    selectedStoreIndex = index;
    const s = stores[index];

    // Update sidebar card
    document.querySelectorAll('.store-card').forEach((c, i) => c.classList.toggle('active', i === index));

    // Update map popup
    const popup = document.getElementById('selectedStoreInfo');
    document.getElementById('selectedStoreName').textContent = s.name;
    document.getElementById('selectedStoreAddr').textContent = `${s.address}, ${s.city}`;
    document.getElementById('selectedStoreHours').textContent = s.hours;
    popup.classList.add('visible');

    // Scroll card into view
    const card = document.getElementById('store-card-' + index);
    if (card) card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function clearSelectedStore() {
    selectedStoreIndex = null;
    document.getElementById('selectedStoreInfo').classList.remove('visible');
    document.querySelectorAll('.store-card').forEach(c => c.classList.remove('active'));
  }

  // Search functionality
  const searchInput = document.getElementById('locatorSearch');
  const suggestions = ['San Francisco, CA', 'Oakland, CA', 'Berkeley, CA', 'Palo Alto, CA', 'San Jose, CA', 'Seattle, WA', 'New York, NY', 'Chicago, IL', 'Austin, TX', 'Boston, MA'];

  searchInput.addEventListener('input', function() {
    const val = this.value.trim().toLowerCase();
    const container = document.getElementById('searchSuggestions');

    if (val.length < 2) {
      container.classList.remove('visible');
      return;
    }

    const matches = suggestions.filter(s => s.toLowerCase().includes(val));
    if (matches.length === 0) {
      container.classList.remove('visible');
      return;
    }

    container.innerHTML = matches.map(m => `
      <div class="suggestion-item" onclick="selectSuggestion('${m}')">
        <span>📍</span> ${m}
      </div>
    `).join('');
    container.classList.add('visible');
  });

  function selectSuggestion(val) {
    searchInput.value = val;
    document.getElementById('searchSuggestions').classList.remove('visible');
    applyFilters(); // "refresh" results
  }

  document.addEventListener('click', function(e) {
    if (!searchInput.contains(e.target)) {
      document.getElementById('searchSuggestions').classList.remove('visible');
    }
  });

